from pathlib import Path
import json,html,re,shutil,sys
from story import S
root=Path(__file__).resolve().parents[1];dist=root/'dist'
design=Path(sys.argv[1]) if len(sys.argv)>1 else root/'contracts'
if design.resolve()!=(root/'contracts').resolve():
 shutil.copytree(design,root/'contracts',dirs_exist_ok=True,ignore=shutil.ignore_patterns('bin','obj','__pycache__'));design=root/'contracts'
(dist/'code').mkdir(exist_ok=True);(dist/'evidence').mkdir(exist_ok=True)
E=html.escape
catalog={};files=[]
for p in sorted((design/'src').glob('**/*.cs')):
 name=p.name;lines=p.read_text().splitlines();files.append(name);(dist/'code'/name).write_text(p.read_text())
 for i,line in enumerate(lines):
  m=re.match(r'public (?:sealed |abstract |readonly )*(?:record struct|record|interface|enum) (\w+)',line)
  if not m:continue
  end=i;balance=0;opened=False
  for j in range(i,len(lines)):
   v=lines[j];balance+=v.count('{')-v.count('}');opened=opened or '{' in v;end=j
   if (opened and balance==0) or (not opened and ';' in v):break
  catalog[m[1]]=dict(file=name,line=i+1,text='\n'.join(lines[i:end+1]))
for step in S:
 for symbol in step['refs']:assert symbol in catalog,symbol
(dist/'story.json').write_text(json.dumps(S,indent=2)+'\n');(dist/'code-index.json').write_text(json.dumps(catalog,indent=2)+'\n')
for p in (design/'docs').glob('*'):
 if p.suffix in ('.md','.json','.png','.svg'):shutil.copy2(p,dist/'evidence'/p.name)
shutil.copy2(design/'OPEN-WORK.md',dist/'evidence/OPEN-WORK.md')
for p in (design/'schemas').glob('*.json'):shutil.copy2(p,dist/'evidence'/p.name)
for p in (design/'examples').glob('*.json'):shutil.copy2(p,dist/'evidence'/p.name)

def shell(title,body,active='',script='atlas.js'):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#11181f"><meta name="description" content="Sattle: explore the master graph, composable projections and typed contracts in 21 animated explanations."><title>{E(title)} · Sattle</title><link rel="stylesheet" href="atlas-next.css">{f'<script defer src="{script}"></script>' if script else ''}</head><body><a class="skip" href="#main">Skip to content</a><header class="header"><a class="brand" href="index.html"><span class="brand-icon" aria-hidden="true">◈</span> Sattle <small>Graph projection atlas</small></a><nav aria-label="Main navigation">{''.join(f'<a href="{url}" '+('aria-current="page"' if key==active else '')+f'>{label}</a>' for key,url,label in [('map','index.html','Map'),('guide','index.html#guide','21 steps'),('code','reference.html','Contracts'),('research','research.html','Research')])}</nav></header><main id="main" tabindex="-1">{body}</main><footer class="footer"><a href="index.html">Sattle</a><span>Graph projections and C# contracts</span><a href="#main">Back to top ↑</a></footer></body></html>'''

def steps_list():
 return ''.join(f'<a class="step-link role-{s["roles"][0]["id"]}" href="step-{s["number"]:02}.html" data-step="{s["number"]}"><span class="step-num">{s["number"]:02}</span><span><small>{E(s["group"])}</small><strong>{E(s["short"])}</strong></span><span class="step-arrow" aria-hidden="true">↗</span></a>' for s in S)

home='''<section class="intro wrap"><div><p class="eyebrow">The graph transformation engine</p><h1>The master graph<br><span>and its projections.</span></h1></div><p class="intro-copy">Derive service, business and document views from shared graph data.<br>Select a capability on the map or follow the 21-step guide.</p></section><section class="landscape wrap" aria-labelledby="map-title"><div class="section-top"><h2 id="map-title">The Wardley map</h2><a class="text-link" href="#guide">Explore all 21 concepts ↓</a></div><p class="map-caption">The map connects user needs to the capabilities and infrastructure they depend on. Select a capability for its guide steps and sources.</p><div class="map-scroll" tabindex="0" role="region" aria-label="Wardley map; scroll horizontally on small screens"><div id="landscape-map" class="landscape-map"><div class="visibility"><span>Visible to the user</span><span>Supporting capabilities</span></div><svg class="map-lines" aria-hidden="true"></svg><div id="landscape-nodes"></div><div class="evolution"><span>Genesis</span><span>Custom built</span><span>Product</span><span>Commodity</span></div></div></div><label class="map-select-label">Explore a capability<select id="capability-select"></select></label><div id="map-detail" class="map-detail" aria-live="polite"></div></section><section class="guide-section wrap" id="guide"><div class="section-top"><div><p class="eyebrow">The 21-step guide</p><h2>Explore the engine.</h2></div><span id="guide-progress" class="progress-label">0 of 21 explored</span></div><p class="section-lead">Each step demonstrates a state change and links to the relevant C# declarations.</p><div class="guide-list">'''+steps_list()+'''</div></section><section class="reference-callout wrap"><div><p class="eyebrow">Code and verification</p><h2>Read the interfaces and schemas.</h2><p>Five contract assemblies, generated wire schemas and a finite reference model with reproducible test reports.</p></div><a class="button primary" href="reference.html">Inspect the contracts →</a></section>'''
(dist/'index.html').write_text(shell('The map',home,'map'))
for s in S:
 n=s['number'];refs=''.join(f'<a class="symbol" href="code-{catalog[x]["file"]}.html#L{catalog[x]["line"]}">{E(x)} ↗</a>' for x in s['refs'])
 excerpt=catalog[s['refs'][0]]
 prev=f'<a href="step-{n-1:02}.html">← {E(S[n-2]["short"])}</a>' if n>1 else '<a href="index.html">← The map</a>'
 nxt=f'<a href="step-{n+1:02}.html">{E(S[n]["short"])} →</a>' if n<21 else '<a href="reference.html">Inspect all contracts →</a>'
 body=f'''<article class="lesson wrap" data-lesson="{n}"><div class="lesson-top"><a href="index.html#guide">← All concepts</a><label class="jump-label">Jump to step <select id="step-select">{''.join(f'<option value="{x["number"]}" '+('selected' if x['number']==n else '')+f'>{x["number"]:02} · {E(x["short"])}</option>' for x in S)}</select></label></div><header class="lesson-heading"><p class="eyebrow"><span class="accent-number">{n:02}</span> / 21 · {E(s['group'])}</p><h1>{E(s['short'])}</h1><p class="lesson-intro">{E(s['intro'])}</p></header><section class="demonstration" aria-label="Animated concept demonstration"><div class="demo-stage"><div class="demo-toolbar"><span class="demo-label">Contract illustration</span><div><button id="zoom-scene" aria-pressed="false">Zoom</button><button id="scroll-mode" aria-pressed="false">Scroll</button><button id="restart" aria-label="Restart demonstration">↺ Restart</button><button id="play" aria-pressed="false">▶ Play</button></div></div><div class="visual-key" aria-label="Color roles">{''.join(f'<span class="role-chip role-{x["id"]}"><i></i>{E(x["label"])}</span>' for x in s["roles"])}</div><div id="scene" class="scene"></div><div class="change-key"><span class="activation-key">◉ Active</span><span>+ Added</span><span>− Removed</span><span>Δ Changed</span><span>× Rejected</span></div><pre id="formula" class="formula"></pre><label class="timeline-label" for="timeline">Slide through the change <span id="timeline-position">1 / 4</span></label><input id="timeline" class="timeline" type="range" min="0" max="3" step="1" value="0" aria-label="Animation phase"><div class="phase-controls" role="group" aria-label="Demonstration phases">{''.join(f'<button data-phase="{i}" aria-label="Phase {i+1}: {E(f["title"])}"><span>{i+1:02}</span><b>{E(f["title"])}</b></button>' for i,f in enumerate(s['frames']))}</div><div class="frame-description" aria-live="polite"><p class="eyebrow" id="frame-label"></p><h2 id="frame-title"></h2><p id="frame-copy"></p></div></div></section><section class="rule-section"><div><p class="eyebrow">The rule</p><h2>What the contract requires</h2><p>{E(s['rule'])}</p></div><div><p class="eyebrow">The boundary</p><h2>Scope and constraints</h2><p>{E(s['limit'])}</p></div></section><section class="code-section"><div class="section-top"><div><p class="eyebrow">C# declaration</p><h2>Contract references</h2></div><a href="reference.html">All modules →</a></div><div class="symbol-links">{refs}</div><div class="code-filebar"><span>{E(excerpt['file'])} · line {excerpt['line']}</span><a href="code-{excerpt['file']}.html#L{excerpt['line']}">View in source ↗</a></div><pre class="code-block"><code>{E(excerpt['text'])}</code></pre><p class="code-note">Excerpt from the contract source. Open the file to see its surrounding declarations.</p></section><section class="read-more" id="lesson-research"><p class="eyebrow">Related research</p><div id="lesson-sources"></div></section><nav class="lesson-pagination" aria-label="Guide navigation">{prev}{nxt}</nav></article>'''
 (dist/f'step-{n:02}.html').write_text(shell(s['short'],body,'guide'))

modules=[('Sattle.Model','Identity, values, ontology and graph changes.','Model.cs'),('Sattle.Projections','Portable definitions, typed expressions and compilation.','Projection.cs'),('Sattle.Runtime','Async ingestion, graph access, configuration and commits.','Ports.cs'),('Sattle.Adapters','Native source formats and graph observations.','Adapters.cs'),('Sattle.Documents','Stable document structure, patches and rendering.','Documents.cs')]
ref='''<section class="wrap reference-page"><p class="eyebrow">Design iteration 0.1</p><h1>C# interfaces<br><span>and schemas.</span></h1><p class="section-lead">The production source contains records, enums and interfaces. Engine behavior is specified in the design documents and exercised by a small test-only mathematical model. The production engine is unimplemented.</p><div class="evidence-numbers"><div><b>5</b><span>contract assemblies</span></div><div><b>12</b><span>generated wire schemas</span></div><div><b>1,921</b><span>finite-model assertions</span></div><div><b>47 + 8</b><span>schema and compile checks</span></div></div><div class="download-row"><a class="button primary" href="sattle-design-v0.1.zip" download>Download the design ↓</a><a href="evidence/VERIFICATION.md">Verification report ↗</a><a href="evidence/OPEN-WORK.md">Open work ↗</a></div><h2>Five modules</h2><p class="section-lead">The interfaces encapsulate storage, scheduling and source formats. Internal processing stages remain within their owning modules.</p><div class="module-list">'''
for name,desc,file in modules:ref+=f'<a class="module-row" href="code-{file}.html"><strong>{name}</strong><span>{desc}</span><b>↗</b></a>'
ref+='</div><div class="additional-files"><a href="code-GraphComposition.cs.html">Master graph and composition →</a><a href="code-ChangeAlgebra.cs.html">Patch and delta arithmetic →</a></div><h2>Master and derived graphs</h2><p>A graph space declares the master. Derived graphs bind master or upstream outputs by name, with separate input and output ontology pins. Each derived graph records the versions it consumed.</p><a href="step-09.html">Explore stacked projections →</a><h2>Design documents and test reports</h2><div class="evidence-list">'
for file,label in [('ARCHITECTURE.md','Architecture and module boundaries'),('VERIFICATION.md','Test scope and limits'),('REVIEWS.md','Counter-reviews and resulting changes'),('DECISIONS.md','Accepted decisions and proposals'),('SOURCES.md','Research and primary sources'),('ADAPTERS.md','Five source families'),('schema-test-results.json','47 schema and selected semantic checks'),('reference-test-results.json','14 finite-model test groups'),('compiler-test-results.json','8 C# positive and negative compile cases'),('graph-space.json','Master, stacked and combined graph example'),('GraphSpaceDefinition.schema.json','Strict graph-space wire schema')]:ref+=f'<a href="evidence/{file}">{label}<span>↗</span></a>'
ref+='''</div><h2>Verification scope</h2><p>The contracts compile with warnings treated as errors. Selected finite examples exercise diff laws, stable identities, lens laws, document edits, recursion and cross-ontology composition. Invalid fixtures demonstrate rejection.</p><p>Production execution, general transformation correctness, distributed consistency, throughput and bounded memory remain unverified. The open-work checklist tracks these obligations.</p><h2>Earlier experiments and decisions.</h2><div class="additional-files"><a href="evaluation.html">Evaluation design and ADRs →</a><a href="examples.html">System and clinical examples →</a><a href="lab.html#transformation">Interactive TGG lab →</a></div></section>'''
(dist/'reference.html').write_text(shell('Contracts',ref,'code'))
for file in files:
 lines=(dist/'code'/file).read_text().splitlines();body=f'<section class="wrap source-page"><a href="reference.html">← All contracts</a><p class="eyebrow">C# source</p><h1>{E(file)}</h1><div class="source-tools"><span>{len(lines)} lines · contract definitions only</span><a href="code/{file}" download>Download source ↓</a></div><div class="source-code">'+''.join(f'<div id="L{i+1}" class="source-line"><a href="#L{i+1}" aria-label="Line {i+1}">{i+1}</a><code>{E(line) or " "}</code></div>' for i,line in enumerate(lines))+'</div></section>'; (dist/f'code-{file}.html').write_text(shell(file,body,'code',None))
land=json.loads((dist/'landscape.json').read_text());research='''<section class="wrap research-page"><p class="eyebrow">Research behind the design</p><h1>Papers and<br><span>technical references.</span></h1><p class="section-lead">Research on graph transformation, streaming dataflow, graph systems and observability informs the design. Sattle’s verification results are listed separately on the Contracts page.</p><div class="paper-grid">'''
for x in land['sources']:research+=f'<article class="paper"><p class="eyebrow">{E(x["type"])} · {E(x["year"])}</p><h2><a href="{E(x["url"])}" target="_blank" rel="noopener noreferrer">{E(x["title"])} ↗</a></h2><p>{E(x["note"])}</p></article>'
research+='</div><div class="additional-files"><a href="evidence/SOURCES.md">Contract design bibliography →</a><a href="lab.html#transformation">Earlier TGG laboratory →</a></div></section>'
(dist/'research.html').write_text(shell('Research',research,'research'))
print(f'Generated {len(S)} lessons and {len(files)} source pages; {len(catalog)} real symbols.')
